UPDATE pays SET prefixe_url = 'ca' WHERE code = 'CA';


  'Divisions (votes nominaux) de la Chambre des communes, législature en cours, d''après les données ouvertes officielles : décomptes et résultat officiels, vote de chaque député (Yea, Nay), mandats et caucus datés. Lancer ensuite les statistiques.', 71, false, 'CA'),
 ('canada_historique', 'Canada : historique (43e et 44e législatures, 2019-2025)',
